return Flux.fromIterable(packet.samples())
    .map(sample -> policy.validate(sample))
    .map(validated -> new TelemetrySampleEvent(
        validated.deviceId(),
        validated.metric(),
        validated.value(),
        validated.tDevice(),
        validated.tIngress(),
        validated.status() == ValidationStatus.VALID
            ? TelemetrySampleEvent.VALID
            : TelemetrySampleEvent.VALIDATION_FAILED))
    .concatMap(event -> {
        Mono<Void> published = validatedSamples.publish(event);
        return published.thenReturn(1);
    })
    .reduce(0, (total, one) -> total + one);

